config.script:
// confirmacao_diaria — agente `script` (MACRO). Comportamento = ESTE arquivo (DADO).
//
// UMA vez por dia (trigger cron), junta os agendamentos de HOJE + AMANHÃ que o paciente
// ainda NÃO confirmou (sem RSVP, não confirmados pela recepção, públicos, fora de status
// terminal) e dispara UMA campanha WhatsApp com o HSM `confirmar_presenca` (1 destinatário
// por agendamento). A RESPOSTA do botão volta sozinha pelo time `confirmacao-presenca` —
// este agente só faz a IDA. Editar isto = editar este .js + re-importar (sem rebuild).
//
// ANTECEDÊNCIA MÍNIMA (mesmo dia): não faz sentido pedir confirmação de uma consulta que já
// está muito perto. Então, para HOJE, só entram agendamentos que começam a partir de
// `agora + min_lead_minutos`. Para AMANHÃ, sem filtro de horas.
//
// FUSO: toda decisão de "que dia é" e todo horário exibido saem do EPOCH ABSOLUTO do ISO
// (Date.parse respeita offset/Z) trazido pro fuso da clínica (tz_offset). NUNCA fatiar a
// string ISO — a API pode devolver em UTC (default TIMEZONE=UTC) e o fatiamento erraria a
// virada de meia-noite.
//
// Injetados: event, config, context, call()->{ok,status_code,body}, log().
// config (editável por-clínica, sem redeploy):
//   min_lead_minutos  antecedência mínima p/ o MESMO DIA (default 120 = 2h)
//   tz_offset         "-03:00" (Brasil sem DST desde 2019) — fuso da clínica
//   status_pular      status a ignorar (cancelado/falta/etc), case-insensitive
//   per_page          teto da paginação do agendamento (<=100)
//   canal_policy      "so_whatsapp"
//   template_slug     "confirmar_presenca" (HSM APPROVED)
//   nome_campanha     prefixo do nome da campanha do dia

var cfg = config || {};
var minLeadMin = (cfg.min_lead_minutos !== undefined && cfg.min_lead_minutos !== null) ? cfg.min_lead_minutos : 120;
var tzOffset = cfg.tz_offset || '-03:00';
var statusPular = cfg.status_pular || ['Cancelado', 'Falta', 'Atendido', 'Realizado'];
var perPage = cfg.per_page || 100;
var canalPolicy = cfg.canal_policy || 'so_whatsapp';
var templateSlug = cfg.template_slug || 'confirmar_presenca';
var nomeCampanha = cfg.nome_campanha || 'Confirmação diária';
var LOTE_MAX = 500;   // teto de destinatários por campanha (contrato da mensageria)
var MAX_PAGINAS = 30; // freio de segurança

function unwrap(r) {
  if (!r || !r.ok) return null;
  var b = r.body;
  return (b && b.data !== undefined) ? b.data : b;
}

// "-03:00" -> minutos (-180). Fallback -180 se malformado.
function offsetMin(s) {
  var m = /^([+-])(\d{2}):(\d{2})$/.exec(String(s));
  if (!m) return -180;
  var val = parseInt(m[2], 10) * 60 + parseInt(m[3], 10);
  return m[1] === '-' ? -val : val;
}
function pad(n) { return (n < 10 ? '0' : '') + n; }

// Componentes de um instante (epoch ms) NO FUSO DA CLÍNICA. Independe de como o ISO veio.
function partesLocais(ms) {
  var d = new Date(ms + offsetMin(tzOffset) * 60000);
  return {
    data: d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()),
    dia: pad(d.getUTCDate()), mes: pad(d.getUTCMonth() + 1),
    hh: pad(d.getUTCHours()), mm: pad(d.getUTCMinutes())
  };
}
function dataHoraBR(p) { return p.dia + '/' + p.mes + ' às ' + p.hh + ':' + p.mm; }

// Nome do serviço a partir dos itens da venda (procedimento > pacote > produto), se houver.
function servicoNome(ag) {
  var venda = ag.venda;
  if (venda && venda.itens && venda.itens.length) {
    for (var i = 0; i < venda.itens.length; i++) {
      var it = venda.itens[i] || {};
      if (it.procedimento_nome) return it.procedimento_nome;
      if (it.pacote_nome) return it.pacote_nome;
      if (it.produto_nome) return it.produto_nome;
    }
  }
  return null; // sem venda -> o template cai no default('consulta')
}

// ---- referências temporais (tudo em epoch absoluto + fuso da clínica) ----
var nowMs = Date.now();
var cutoffMs = nowMs + minLeadMin * 60000;      // limite inferior p/ o MESMO DIA
var hoje = partesLocais(nowMs).data;            // "YYYY-MM-DD" na clínica
var amanha = partesLocais(nowMs + 86400000).data;

// Janela de busca: hoje 00:00 -> amanhã 23:59 (fuso da clínica). O recorte fino de horas do
// mesmo dia é feito abaixo (cutoff), pra não depender de igualdade de fuso no filtro do backend.
var ini = hoje + 'T00:00:00' + tzOffset;
var fim = amanha + 'T23:59:59' + tzOffset;

var pular = {};
for (var s = 0; s < statusPular.length; s++) pular[String(statusPular[s]).toLowerCase()] = true;

// ---- 1) coleta paginada + recorte (dia/antecedência/privacidade/status) ----
var pendentes = [];
var pagina = 1;
while (pagina <= MAX_PAGINAS) {
  var lista = unwrap(call('listar_nao_confirmados', {
    data_inicio: ini, data_fim: fim,
    confirmado: 'false', rsvp_cliente: 'sem_resposta', // só os pendentes de verdade
    per_page: perPage, page: pagina
  }));
  if (!lista || !lista.length) break;
  for (var k = 0; k < lista.length; k++) {
    var ag = lista[k];
    if (!ag || !ag.id) continue;
    if (ag.visibilidade && String(ag.visibilidade) !== 'publica') continue; // privacidade da plataforma
    if (ag.status && pular[String(ag.status).toLowerCase()]) continue;       // cancelado/falta/etc
    if (!ag.cliente_id) continue;                                            // sem cliente não há p/ quem enviar

    var startMs = Date.parse(ag.data_inicio); // epoch absoluto (respeita offset/Z)
    if (isNaN(startMs)) continue;             // início não-parseável -> não dá p/ decidir/exibir
    var loc = partesLocais(startMs);
    if (loc.data === hoje) {
      if (startMs < cutoffMs) continue;       // mesmo dia: respeita a antecedência mínima
    } else if (loc.data !== amanha) {
      continue;                               // fora de hoje/amanhã (borda de fuso) -> ignora
    }
    ag.__loc = loc;                           // guarda p/ montar data_hora sem reparsing
    pendentes.push(ag);
  }
  if (lista.length < perPage) break; // última página
  pagina++;
}

if (!pendentes.length) {
  log('confirmacao_diaria: nenhum agendamento pendente (janela ' + ini + '..' + fim + ', lead ' + minLeadMin + 'min)');
  return { ok: true, pendentes: 0, campanhas: 0, janela: { de: ini, ate: fim }, min_lead_minutos: minLeadMin };
}

// ---- 2) monta destinatários (1 por agendamento; correlação p/ o RSVP voltar) ----
var destinatarios = [];
for (var p = 0; p < pendentes.length; p++) {
  var a = pendentes[p];
  var vars = { data_hora: dataHoraBR(a.__loc) }; // única var do template SEM default -> obrigatória
  var sv = servicoNome(a);
  if (sv) vars.servico_nome = sv;
  // cliente_nome e profissional_apelido NÃO vêm da lista -> o template usa os defaults
  // ('paciente' / 'a clínica'). Pra personalizar, ver "Enrich opcional" no README.
  destinatarios.push({
    cliente_id: String(a.cliente_id),   // a mensageria resolve o telefone no disparo
    variaveis: vars,
    referencia_tipo: 'agendamento',
    referencia_id: String(a.id)         // <- o botão volta AMARRADO a este agendamento
  });
}

// ---- 3) dispara em lotes de até 500 (agendar_para omitido => dispara já) ----
var campanhas = 0, enviados = 0;
var multi = destinatarios.length > LOTE_MAX;
for (var base = 0; base < destinatarios.length; base += LOTE_MAX) {
  var lote = destinatarios.slice(base, base + LOTE_MAX);
  var nome = nomeCampanha + ' (' + hoje + ')' + (multi ? ' #' + (campanhas + 1) : '');
  var r = call('disparar_campanha', {
    nome: nome,
    canal_policy: canalPolicy,
    template_slug: templateSlug,
    variaveis_base: {},
    destinatarios: lote,
    referencia_tipo: 'agendamento',
    rascunho: false
  });
  if (r && r.ok) { campanhas++; enviados += lote.length; }
  else { log('confirmacao_diaria: FALHA no lote ' + (campanhas + 1) + ' HTTP ' + (r && r.status_code)); }
}

log('confirmacao_diaria: ' + pendentes.length + ' pendente(s) -> ' + campanhas + ' campanha(s), ' + enviados + ' destinatário(s)');
return {
  ok: true,
  pendentes: pendentes.length,
  campanhas: campanhas,
  destinatarios: enviados,
  janela: { de: ini, ate: fim },
  min_lead_minutos: minLeadMin
};
